<template>
	<div class="flex min-h-dvh flex-col bg-ui-surface-gray-50">
		<!-- ============ HEADER ============ -->
		<div
			class="sticky top-0 z-30 border-b border-ui-line-gray-200 bg-ui-surface px-5 py-4"
			style="padding-top: calc(1rem + env(safe-area-inset-top))"
		>
			<div class="flex items-center gap-2">
				<RouterLink
					:to="{ name: 'Resi' }"
					class="-ml-1 flex h-10 w-10 shrink-0 items-center justify-center rounded-md text-primary transition-colors hover:bg-ui-surface-blue-50 active:bg-ui-surface-blue-100"
					title="Kembali"
					aria-label="Kembali"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-7 w-7"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m12 19-7-7 7-7" />
						<path d="M19 12H5" />
					</svg>
				</RouterLink>
				<span class="min-w-0 truncate font-medium text-ui-ink-gray-900">{{ name }}</span>
			</div>

			<!-- Tab top-level (gaya sama dengan Data Pengajuan): underline + ikon,
			     menempel di header supaya ikut sticky tanpa mengukur tinggi header. -->
			<div class="-mx-5 -mb-4 mt-3 flex px-5">
				<button
					v-for="tab in TABS"
					:key="tab.key"
					type="button"
					class="-mb-px flex flex-1 items-center justify-center gap-1.5 whitespace-nowrap border-b-2 px-3 py-3 text-sm font-medium transition"
					:class="
						activeTab === tab.key
							? 'border-ui-line-gray-800 text-ui-ink-gray-900'
							: 'border-transparent text-ui-ink-gray-500 hover:text-ui-ink-gray-700'
					"
					@click="activeTab = tab.key"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-4 w-4"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
						v-html="tab.icon"
					/>
					{{ tab.label }}
				</button>
			</div>
		</div>

		<!-- ============ BODY ============ -->
		<div class="flex flex-1 flex-col">
			<div class="app-container-narrow space-y-4 px-4 py-5 text-base md:px-6">
				<p v-if="loading" class="py-10 text-center text-sm text-ui-ink-gray-400">Memuat…</p>
				<pre
					v-else-if="loadError"
					class="rounded-md border border-ui-line-red-200 bg-ui-surface-red-50 px-3 py-2 text-sm text-ui-ink-red-700 whitespace-pre-wrap"
					>{{ loadError }}</pre
				>

				<template v-else-if="doc">
					<!-- Status + peringatan field kosong -->
					<div
						class="flex flex-wrap items-center gap-2 rounded-xl border px-3 py-2.5 text-sm"
						:class="statusBanner.wrap"
					>
						<span
							class="inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-semibold"
							:class="statusBanner.badge"
						>
							{{ doc.status || '—' }}
						</span>
						<span v-if="emptyNote" class="min-w-0 font-medium">{{ emptyNote }}</span>
					</div>

					<!-- Catatan validasi / duplikat -->
					<div
						v-if="doc.catatan_validasi"
						class="rounded-xl border px-3 py-2.5 text-sm"
						:class="kelasCatatanValidasi"
					>
						{{ doc.catatan_validasi }}
					</div>

					<!-- ============ TAB: Detail ============ -->
					<template v-if="activeTab === 'detail'">
						<!-- Pratinjau bukti transfer -->
						<div
							v-if="doc.gambar_resi"
							class="overflow-hidden rounded-2xl border border-ui-line-gray-100 bg-ui-surface shadow-sm"
						>
							<img
								:src="doc.gambar_resi"
								alt="Bukti transfer"
								class="mx-auto max-h-[440px] w-auto max-w-full object-contain"
							/>
						</div>

						<!-- Section & field mengikuti susunan doctype yang dikirim server.
						     Field yang boleh dikoreksi tampil sebagai input, sisanya sebagai
						     baris info. Menambah field, mengubah label, atau mengunci field
						     di desk langsung ikut tanpa mengubah halaman ini. -->
						<section
							v-for="(sec, i) in sections"
							:key="i"
							class="rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-4 shadow-sm md:p-5"
						>
							<button
								v-if="sec.label && sec.collapsible"
								type="button"
								class="-m-1 mb-2 flex w-full appearance-none items-center justify-between gap-2 rounded-lg p-1 text-left transition-colors hover:bg-ui-surface-gray-50"
								:aria-expanded="!sectionTertutup(i)"
								@click="toggleSection(i)"
							>
								<span class="truncate text-sm font-semibold text-primary">
									{{ sec.label }}
								</span>
								<svg
									xmlns="http://www.w3.org/2000/svg"
									viewBox="0 0 24 24"
									class="h-4 w-4 shrink-0 text-ui-ink-gray-400 transition-transform"
									:class="{ '-rotate-90': sectionTertutup(i) }"
									fill="none"
									stroke="currentColor"
									stroke-width="2"
									stroke-linecap="round"
									stroke-linejoin="round"
								>
									<path d="m6 9 6 6 6-6" />
								</svg>
							</button>
							<h2
								v-else-if="sec.label"
								class="mb-3 text-sm font-semibold text-primary"
							>
								{{ sec.label }}
							</h2>
							<div v-show="!sectionTertutup(i)" class="space-y-3">
								<template v-for="f in sec.fields" :key="f.fieldname">
									<label
										v-if="bisaEdit(f) && f.fieldtype === 'Check'"
										class="flex items-center gap-2"
									>
										<input
											v-model="form[f.fieldname]"
											type="checkbox"
											class="h-4 w-4 rounded border-ui-line-gray-300"
										/>
										<span class="text-sm text-ui-ink-gray-700">{{ f.label }}</span>
									</label>

									<div v-else-if="bisaEdit(f)">
										<label :class="labelClass">{{ f.label }}</label>
										<select
											v-if="f.fieldtype === 'Select'"
											v-model="form[f.fieldname]"
											:class="inputClass"
										>
											<option value="">&#8212;</option>
											<option v-for="o in opsiSelect(f)" :key="o" :value="o">
												{{ o }}
											</option>
										</select>
										<textarea
											v-else-if="tipeInput(f) === 'textarea'"
											v-model="form[f.fieldname]"
											rows="3"
											:class="inputClass"
										/>
										<input
											v-else
											v-model="form[f.fieldname]"
											:type="tipeInput(f)"
											:inputmode="
												tipeInput(f) === 'number' ? 'numeric' : undefined
											"
											:class="inputClass"
										/>
										<p v-if="f.description" class="mt-1 text-xs text-ui-ink-gray-400">
											{{ f.description }}
										</p>
									</div>

									<!-- Nilai panjang (JSON mentah, hash) dirender sebagai blok
									     penuh: rata kanan ala InfoRow membuatnya jadi dinding
									     teks yang tak terbaca di layar HP. -->
									<div v-else-if="tampil(f) && nilaiPanjang(f)">
										<div :class="labelClass">{{ f.label }}</div>
										<pre
											class="max-h-56 overflow-auto whitespace-pre-wrap break-all rounded-md border border-ui-line-gray-200 bg-ui-surface-gray-50 px-3 py-2 text-left font-mono text-xs leading-relaxed text-ui-ink-gray-600"
											>{{ tampil(f) }}</pre
										>
									</div>

									<dl v-else-if="tampil(f)">
										<InfoRow :label="f.label" :value="tampil(f)" />
									</dl>
								</template>
							</div>
						</section>
					</template>

					<!-- ============ TAB: Comments ============ -->
					<div v-else-if="activeTab === 'comments'">
						<div class="mb-5 flex items-center justify-between">
							<h2 class="text-lg font-semibold text-ui-ink-gray-900">Comments</h2>
							<button
								type="button"
								class="rounded-lg bg-primary px-3 py-1.5 text-sm font-medium text-ui-onPrimary transition hover:opacity-90"
								@click="comments.showForm = !comments.showForm"
							>
								+ New Comment
							</button>
						</div>

						<!-- Form tambah comment. Input mention (@user) meniru desk Frappe:
						     ketik '@' → daftar user, pilih → chip; server mengirim
						     Notification Log "Mention" ke user yang di-tag. -->
						<div v-if="comments.showForm" class="mb-5">
							<MentionInput
								v-model="comments.body"
								placeholder="Tulis komentar… ketik @ untuk menandai user"
								:priority-users="mentionPriorityUsers"
								:disabled="comments.submitting"
								@submit="submitComment"
							/>
							<div class="mt-2 flex items-center gap-2">
								<button
									type="button"
									:disabled="comments.submitting || !commentHasText"
									class="rounded-lg bg-primary px-4 py-2 text-sm font-medium text-ui-onPrimary transition hover:opacity-90 disabled:cursor-not-allowed disabled:opacity-50"
									@click="submitComment"
								>
									{{ comments.submitting ? 'Mengirim…' : 'Kirim' }}
								</button>
								<button
									type="button"
									class="rounded-lg border border-ui-line-gray-300 px-4 py-2 text-sm font-medium text-ui-ink-gray-700 transition hover:bg-ui-surface-gray-50"
									@click="cancelComment"
								>
									Batal
								</button>
							</div>
						</div>

						<p v-if="comments.loading" class="text-base text-ui-ink-gray-500">Loading...</p>
						<pre
							v-else-if="comments.error"
							class="text-base text-ui-ink-red-600 whitespace-pre-wrap"
							>{{ comments.error }}</pre
						>
						<p v-else-if="!comments.items.length" class="text-base text-ui-ink-gray-400">
							Belum ada komentar.
						</p>

						<ul v-else class="space-y-4">
							<li
								v-for="c in comments.items"
								:key="c.name"
								class="rounded-lg border border-ui-line-gray-200 bg-ui-surface"
							>
								<div class="flex flex-wrap items-center gap-2 px-3 py-2 text-base">
									<span
										class="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-ui-surface-orange-100 text-[10px] font-semibold text-ui-ink-orange-700"
									>
										{{ initials(c.comment_by || c.owner) }}
									</span>
									<span class="font-medium text-ui-ink-gray-900">{{
										c.comment_by || c.owner
									}}</span>
									<span class="text-ui-ink-gray-500">added a comment</span>
									<span class="text-ui-ink-gray-400">· {{ timeAgo(c.creation) }}</span>
								</div>
								<div
									class="px-3 pb-3 pl-11 text-sm text-ui-ink-gray-700"
									v-html="c.content"
								/>
							</li>
						</ul>
					</div>
				</template>
			</div>
		</div>

		<!-- ============ ACTION BAR ============ -->
		<!-- Tombol dihitung server dari status + hak user. Tidak ada tombol berarti
		     dokumen sedang dikunci alur (mis. Diproses, Proses Finance, Resi OK). -->
		<div
			v-if="actions.length"
			class="sticky bottom-0 z-20 flex gap-2 border-t border-ui-line-gray-200 bg-ui-surface px-4 py-3 md:px-6 bottom-bar"
			style="padding-bottom: calc(0.75rem + env(safe-area-inset-bottom))"
		>
			<button
				v-for="aksi in actions"
				:key="aksi.name"
				type="button"
				:disabled="busy"
				class="flex flex-1 items-center justify-center rounded-lg py-2.5 text-sm font-medium transition disabled:opacity-50"
				:class="
					aksi.primary
						? 'bg-primary text-ui-onPrimary hover:opacity-90'
						: 'border border-ui-line-gray-300 bg-ui-surface text-ui-ink-gray-700'
				"
				@click="jalankanAksi(aksi)"
			>
				{{ aksi.label }}
			</button>
		</div>

		<!-- ====== Overlay freeze ====== -->
		<Teleport to="body">
			<Transition
				enter-active-class="transition-opacity duration-150"
				enter-from-class="opacity-0"
				leave-active-class="transition-opacity duration-150"
				leave-to-class="opacity-0"
			>
				<div
					v-if="pesanTunggu"
					class="fixed inset-0 z-[100] flex flex-col items-center justify-center gap-4 bg-black/60 px-8 text-center"
				>
					<svg
						class="h-10 w-10 animate-spin text-white"
						xmlns="http://www.w3.org/2000/svg"
						fill="none"
						viewBox="0 0 24 24"
					>
						<circle
							class="opacity-25"
							cx="12"
							cy="12"
							r="10"
							stroke="currentColor"
							stroke-width="4"
						/>
						<path
							class="opacity-75"
							fill="currentColor"
							d="M4 12a8 8 0 0 1 8-8V0C5.4 0 0 5.4 0 12h4z"
						/>
					</svg>
					<p class="text-sm font-medium text-white">
						{{ pesanTunggu }}
					</p>
				</div>
			</Transition>
		</Teleport>

		<!-- Hasil ekstraksi ulang; dialog yang sama dipakai Buat Resi & Aktivitas. -->
		<ResiHasilDialog :isi="hasilResi" @close="hasilResi = null" />
	</div>
</template>

<script setup>
import { computed, h, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { refreshCsrfToken } from '../data/session'
import { currentUser } from '../data/user'
import { notifyError, notifySuccess } from '../composables/toast'
import MentionInput from '../components/MentionInput.vue'
import { ambilKonfigurasiResi, kelasBanner, kelasPill, warnaStatus } from '../data/resiConfig'
import ResiHasilDialog from '../components/ResiHasilDialog.vue'
import { popupHasilResi } from '../data/resiHasil'

const route = useRoute()
const name = route.params.name

// Tab: Detail (hasil ekstraksi) & Comments (doctype Comment, seperti Data Pengajuan).
const TABS = [
	{
		key: 'detail',
		label: 'Detail',
		icon: '<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18"/><path d="M9 21V9"/>',
	},
	{
		key: 'comments',
		label: 'Comments',
		icon: '<path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/>',
	},
]
const activeTab = ref('detail')

const doc = ref(null)
const loading = ref(true)
const loadError = ref('')
const busy = ref(false)
// Teks overlay saat aksi berjalan. Kosong = overlay tersembunyi.
const pesanTunggu = ref('')

// Konfigurasi dari server: susunan field, hak ubah, dan tombol alur.
const config = ref(null)
const form = reactive({})

const sections = computed(() => config.value?.layout || [])

// Index section yang sedang ditutup. Section ber-`collapsible` di doctype mulai
// tertutup mengikuti desk; sisanya selalu terbuka.
const sectionDitutup = ref(new Set())
function sectionTertutup(i) {
	return sectionDitutup.value.has(i)
}
function toggleSection(i) {
	const next = new Set(sectionDitutup.value)
	if (next.has(i)) next.delete(i)
	else next.add(i)
	sectionDitutup.value = next
}
function resetSection() {
	const tutup = new Set()
	sections.value.forEach((sec, i) => {
		if (sec.collapsible) tutup.add(i)
	})
	sectionDitutup.value = tutup
}
const canEdit = computed(() => !!config.value?.can_edit)
// Aksi hanya relevan di tab Detail; daftarnya sudah disaring server sesuai
// status dan hak user, jadi daftar kosong berarti dokumen terkunci alur.
const actions = computed(() => (activeTab.value === 'detail' ? config.value?.actions || [] : []))

// Fieldtype doctype → jenis input HTML. Fieldtype di luar daftar ini (Link,
// Attach Image, Table, …) belum punya editor di aplikasi, jadi ditampilkan
// sebagai baris info saja.
const TIPE_INPUT = {
	Data: 'text',
	'Small Text': 'textarea',
	Text: 'textarea',
	'Long Text': 'textarea',
	Currency: 'number',
	Float: 'number',
	Int: 'number',
	Percent: 'number',
	Date: 'date',
	Datetime: 'datetime-local',
	Time: 'time',
	Select: 'select',
	Check: 'checkbox',
}

function tipeInput(f) {
	return TIPE_INPUT[f.fieldtype] || null
}
function bisaEdit(f) {
	return canEdit.value && !f.read_only && !!tipeInput(f)
}
function opsiSelect(f) {
	return String(f.options || '')
		.split('\n')
		.map((o) => o.trim())
		.filter(Boolean)
}
// Nilai siap tampil untuk field read-only. Kosong → baris disembunyikan.
function tampil(f) {
	const v = doc.value?.[f.fieldname]
	if (v == null || v === '') return ''
	if (f.fieldtype === 'Currency') return rupiah(v)
	if (f.fieldtype === 'Date') return tanggal(v)
	if (f.fieldtype === 'Check') return v ? 'Ya' : 'Tidak'
	return String(v)
}

// Di atas ambang ini teks tidak lagi terbaca sebagai baris rata kanan di HP.
const PANJANG_MAKS_BARIS = 48
function nilaiPanjang(f) {
	// Code selalu blok: isinya JSON mentah, sependek apa pun tetap perlu monospace.
	return f.fieldtype === 'Code' || String(tampil(f)).length > PANJANG_MAKS_BARIS
}
// Nilai awal input diambil dari dokumen, mengikuti field yang dikirim server.
function isiForm() {
	Object.keys(form).forEach((k) => delete form[k])
	sections.value.forEach((sec) => {
		sec.fields.forEach((f) => {
			if (!f.read_only) form[f.fieldname] = doc.value?.[f.fieldname] ?? ''
		})
	})
}

const labelClass = 'mb-1 block text-xs font-medium text-ui-ink-gray-500'
const inputClass =
	'min-h-[44px] w-full rounded-md border border-ui-line-gray-300 bg-ui-surface px-3 py-2 text-sm text-ui-ink-gray-800 outline-none transition focus:border-primary focus:ring-2 focus:ring-inset focus:ring-primary/30 md:min-h-0'

// Baris info kecil (dl). Read-only, cermin field doctype.
const InfoRow = (props) =>
	h('div', { class: 'flex items-start justify-between gap-3' }, [
		h('dt', { class: 'shrink-0 text-sm text-ui-ink-gray-500' }, props.label),
		h(
			'dd',
			{
				class: [
					'min-w-0 break-words text-right text-sm',
					props.strong ? 'font-semibold text-ui-ink-gray-900' : 'font-medium text-ui-ink-gray-800',
				],
			},
			props.value ? String(props.value) : '—'
		),
	])
InfoRow.props = ['label', 'value', 'strong']

// ---- Warna status (mengikuti Document States doctype) ---------------------
const statusBanner = computed(() => {
	const warna = warnaStatus(config.value?.statuses, doc.value?.status)
	return { wrap: kelasBanner(warna), badge: kelasPill(warna) }
})

// ---- Peringatan field kosong ----------------------------------------------
// Daftar field yang dicek beserta labelnya datang dari server (CHECKED_FIELDS),
// sama persis dengan yang dipakai desk.
const emptyNote = computed(() => {
	const d = doc.value
	if (!d || !d.status || d.status === 'Draft' || d.status === 'Diproses') return ''
	const kosong = (config.value?.checked_fields || [])
		.filter((f) => !d[f.fieldname])
		.map((f) => `${f.label} Kosong`)
	return kosong.length ? kosong.join(', ') : ''
})

// ---- Util -----------------------------------------------------------------
function rupiah(v) {
	if (v == null || v === '') return ''
	return 'Rp ' + Number(v).toLocaleString('id-ID')
}
function tanggal(v) {
	if (!v) return ''
	const m = String(v).match(/^(\d{4})-(\d{2})-(\d{2})/)
	return m ? `${m[3]}-${m[2]}-${m[1]}` : String(v)
}
function frappeError(json) {
	try {
		if (json && json._server_messages) {
			const arr = JSON.parse(json._server_messages)
			return arr
				.map((m) => {
					try {
						return JSON.parse(m).message
					} catch (e) {
						return m
					}
				})
				.join('\n')
		}
	} catch (e) {
		/* ignore */
	}
	return (json && (json.exception || json.message)) || ''
}

// ---- Load -----------------------------------------------------------------
async function load() {
	loading.value = true
	loadError.value = ''
	try {
		const params = new URLSearchParams({ doctype: 'Resi', name: String(name) })
		const res = await fetch(`/api/method/frappe.client.get?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		doc.value = json.message
		// Konfigurasi dimuat bersama dokumen: hak ubah dan tombol yang berlaku
		// ikut berubah setiap kali status berubah.
		config.value = await ambilKonfigurasiResi(String(name))
		isiForm()
		resetSection()
	} catch (e) {
		loadError.value = e.message || String(e)
	} finally {
		loading.value = false
	}
}

const METHOD_EKSTRAKSI = 'juragan.juragan.doctype.resi.resi.run_extraction_now'
const hasilResi = ref(null)

// Duplikat & penerima tidak sesuai menggugurkan bukti transfernya, jadi
// catatannya merah; catatan pada resi yang masih berjalan cukup kuning.
const kelasCatatanValidasi = computed(() =>
	['Duplikat', 'Gagal'].includes(doc.value?.status)
		? 'border-ui-line-red-200 bg-ui-surface-red-50 text-ui-ink-red-700'
		: 'border-ui-line-amber-200 bg-ui-surface-amber-50 text-ui-ink-amber-800',
)

// ---- Aksi -----------------------------------------------------------------
async function panggilMethod(method) {
	await refreshCsrfToken()
	const res = await fetch(`/api/method/${method}`, {
		method: 'POST',
		credentials: 'include',
		headers: {
			'Content-Type': 'application/json',
			Accept: 'application/json',
			'X-Frappe-CSRF-Token': window.csrf_token || '',
		},
		body: JSON.stringify({ docname: String(name) }),
	})
	const json = await res.json().catch(() => ({}))
	if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
	return json
}

// Semua tombol dijalankan lewat jalur yang sama: simpan koreksi bila diizinkan,
// lalu panggil method alur milik tombol tersebut. Tombol tanpa method (mis.
// Simpan Perubahan) berhenti setelah menyimpan.
async function jalankanAksi(aksi) {
	busy.value = true
	pesanTunggu.value = aksi.pesan_tunggu || ''
	try {
		if (aksi.simpan_dulu && canEdit.value) {
			await setValues(editedPayload())
		}
		const hasil = aksi.method ? await panggilMethod(aksi.method) : null
		await load()
		// Ekstraksi bisa berakhir Duplikat atau Ditolak dan tetap membalas
		// sukses; toast "selesai" menyembunyikan itu, jadi hasilnya ditampilkan
		// sebagai dialog seperti di desk (frappe.msgprint).
		if (aksi.method === METHOD_EKSTRAKSI) {
			hasilResi.value = popupHasilResi({ name: String(name), ...(hasil?.message || {}) })
			return
		}
		notifySuccess(aksi.pesan_sukses || 'Perubahan tersimpan.')
	} catch (e) {
		notifyError(e, `Gagal: ${aksi.label}`)
	} finally {
		busy.value = false
		pesanTunggu.value = ''
	}
}

// Kirim beberapa field sekaligus: frappe.client.set_value menerima dict pada
// `fieldname`. Status tidak pernah ikut — status hanya berubah lewat method alur.
async function setValues(payload) {
	await refreshCsrfToken()
	const res = await fetch('/api/method/frappe.client.set_value', {
		method: 'POST',
		credentials: 'include',
		headers: {
			'Content-Type': 'application/json',
			Accept: 'application/json',
			'X-Frappe-CSRF-Token': window.csrf_token || '',
		},
		body: JSON.stringify({
			doctype: 'Resi',
			name: String(name),
			fieldname: payload,
		}),
	})
	const json = await res.json().catch(() => ({}))
	if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
	return json
}

// Nilai form siap kirim: hanya field yang benar-benar tampil sebagai input, dan
// string kosong → null supaya field benar-benar dikosongkan.
function editedPayload() {
	const out = {}
	sections.value.forEach((sec) => {
		sec.fields.filter(bisaEdit).forEach((f) => {
			const v =
				typeof form[f.fieldname] === 'string'
					? form[f.fieldname].trim()
					: form[f.fieldname]
			out[f.fieldname] = v === '' || v === undefined ? null : v
		})
	})
	return out
}

// ---- Comments (doctype Comment) -------------------------------------------
const comments = reactive({
	loading: false,
	error: '',
	items: [],
	showForm: false,
	body: '',
	submitting: false,
})

function initials(nameStr) {
	return String(nameStr)
		.split(/\s+/)
		.filter(Boolean)
		.slice(0, 2)
		.map((w) => w[0]?.toUpperCase() || '')
		.join('')
}

function timeAgo(dateStr) {
	if (!dateStr) return ''
	const then = new Date(String(dateStr).replace(' ', 'T'))
	const sec = Math.floor((Date.now() - then.getTime()) / 1000)
	if (sec < 60) return 'just now'
	const min = Math.floor(sec / 60)
	if (min < 60) return `${min} minute${min > 1 ? 's' : ''} ago`
	const hr = Math.floor(min / 60)
	if (hr < 24) return `${hr} hour${hr > 1 ? 's' : ''} ago`
	const d = Math.floor(hr / 24)
	if (d === 1) return 'yesterday'
	if (d < 7) return `${d} days ago`
	const w = Math.floor(d / 7)
	if (w < 5) return `${w} week${w > 1 ? 's' : ''} ago`
	const mo = Math.floor(d / 30)
	if (mo < 12) return `${mo} month${mo > 1 ? 's' : ''} ago`
	const y = Math.floor(d / 365)
	return `${y} year${y > 1 ? 's' : ''} ago`
}

// List comment dokumen ini (GET, tidak butuh CSRF).
// Pakai endpoint portal (bukan client.get_list Comment): role biasa tak punya
// read permission pada doctype Comment → 403. Endpoint menggerbang lewat izin
// BACA Resi lalu query Comment dgn ignore_permissions.
async function loadComments() {
	comments.loading = true
	comments.error = ''
	try {
		const params = new URLSearchParams({ reference_name: String(name) })
		const res = await fetch(
			`/api/method/juragan.api.portal.resi.get_comments?${params.toString()}`,
			{
				method: 'GET',
				credentials: 'include',
				headers: { Accept: 'application/json' },
			}
		)
		if (!res.ok) throw new Error(`HTTP ${res.status}`)
		const json = await res.json()
		comments.items = json.message || []
	} catch (e) {
		comments.error = e.message || String(e)
	} finally {
		comments.loading = false
	}
}

// Isi komentar berupa HTML (dari MentionInput). Tombol Kirim aktif kalau ada
// teks setelah tag dibuang — meniru update_state() ControlComment di desk.
function stripHtmlText(html) {
	if (!html) return ''
	const el = document.createElement('div')
	el.innerHTML = html
	return (el.textContent || '').replace(/[\s ﻿]+/g, ' ').trim()
}
const commentHasText = computed(() => !!stripHtmlText(comments.body))

// User "terlibat" di dokumen ini → didahulukan di daftar mention, seperti
// prioritize_involved_users_in_mention di desk (frm.get_involved_users()).
const mentionPriorityUsers = computed(() => {
	const d = doc.value || {}
	const users = [d.owner, d.modified_by]
	try {
		users.push(...JSON.parse(d._assign || '[]'))
	} catch {
		// _assign bukan JSON valid → abaikan
	}
	comments.items.forEach((c) => users.push(c.comment_email || c.owner))
	return [...new Set(users)].filter((u) => u && u !== 'Administrator' && u !== currentUser.user)
})

// Insert comment baru (POST → butuh CSRF token), lalu refresh list.
async function submitComment() {
	const body = comments.body.trim()
	if (!body || !commentHasText.value) return
	comments.submitting = true
	comments.error = ''
	try {
		await refreshCsrfToken()
		// Pakai add_comment (bukan client.insert Comment): izinnya berbasis akses
		// BACA dokumen Resi, bukan izin CREATE doctype Comment — yang hanya
		// dimiliki System Manager/Website Manager → selain itu 403.
		const res = await fetch('/api/method/frappe.desk.form.utils.add_comment', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({
				reference_doctype: 'Resi',
				reference_name: String(name),
				content: body,
				comment_email: currentUser.user,
				comment_by: currentUser.fullName || currentUser.user,
			}),
		})
		if (!res.ok) throw new Error(`HTTP ${res.status}`)
		comments.body = ''
		comments.showForm = false
		await loadComments()
	} catch (e) {
		comments.error = e.message || String(e)
		notifyError(e, 'Gagal mengirim komentar')
	} finally {
		comments.submitting = false
	}
}

// Tutup form komentar & kosongkan isinya (tombol Batal).
function cancelComment() {
	comments.showForm = false
	comments.body = ''
}

onMounted(() => {
	load()
	loadComments()
})
</script>
